cd /app; python - <<'EOF'
import ast
src=open('tally/reports.py').read()
t=ast.parse(src)
for n in t.body:
    if isinstance(n,(ast.FunctionDef,ast.ClassDef)): print(n.lineno, n.end_lineno, type(n).__name__[:3], n.name)
    elif isinstance(n,ast.Assign): print(n.lineno,n.end_lineno,'asg',[getattr(x,'id',None) for x in n.targets])
    elif isinstance(n,ast.AnnAssign): print(n.lineno,'ann')
    elif isinstance(n,(ast.Import,ast.ImportFrom)): pass
    else: print(n.lineno,n.end_lineno,type(n).__name__)
EOF
